            {(bottom, c) for c in range(left, right+1)} |
            {(r, left) for r in range(top, bottom+1)} |
            {(r, right) for r in range(top, bottom+1)})
    for r, c in edge:
        if out[r][c] == bg: out[r][c] = 2

    # Label source-color components before adding connectors.
    labels = {}; comp = 0
    for start in fg:
        if start in labels: continue
        labels[start] = comp; stack = [start]
        while stack:
            r, c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in fg and q not in labels:
                    labels[q] = comp; stack.append(q)
        comp += 1

    def join_line(p, q, coords):
        # Only short gaps, and only when they connect distinct source pieces.
        if 1 < len(coords) <= 3:
            ids_p = {labels[p]} if p in labels else set()
            ids_q = {labels[q]} if q in labels else set()
            if ids_p and ids_q and ids_p == ids_q:
                return
