def _runs(values, background):
    runs = []
    i = 0
    while i < len(values):
        color = values[i]
        if color == background:
            i += 1
            continue
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        if j - i >= 2:
            runs.append((color, i, j - 1))
        i = j
    return runs


