        # Continue a repeated suffix wherever it is explicit in the row.
        for r, (period, start, end, motif) in periodic.items():
            for c in range(end + 1, w):
                if motif[(c - start) % period] and grid[r][c] == background:
                    out[r][c] = 1

        # A solid terminal run is extended only when it is the dominant run in its component.
        solid_rows = [r for r in rows if terminal[r] >= 5 and r not in periodic]
        if solid_rows:
            best = max(terminal[r] for r in solid_rows)
            for r in solid_rows:
                if terminal[r] == best:
                    for c in range(rightmost[r] + 1, w):
                        if grid[r][c] == background:
                            out[r][c] = 1
        elif len(rows) == 1 and rows[0] not in periodic:
            r = rows[0]
            for c in range(rightmost[r] + 1, w):
                if grid[r][c] == background:
                    out[r][c] = 1
    return out

from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = max((v for v in counts if v != background), key=lambda v: counts[v], default=background)
    out = [row[:] for row in grid]
    active = [any(v == foreground for v in row) for row in grid]
    bands = []
    start = None
    for r, yes in enumerate(active + [False]):
        if yes and start is None:
            start = r
        elif not yes and start is not None:
            bands.append(list(range(start, r)))
            start = None

    # When a later band repeats an earlier band but is cut off, use the earlier one as a template.
    copied = set()
    for j, target in enumerate(bands):
        for i in range(j):
            source = bands[i]
            if len(source) != len(target):
                continue
            common = min(next((c for c in range(w) if grid[a][c] != grid[b][c]), w)
                         for a, b in zip(source, target))
            if common < 0.7 * w or common == w:
                continue
            changed = False
            for a, b in zip(source, target):
                for c in range(common, w):
                    if grid[a][c] == foreground and grid[b][c] == background:
                        out[b][c] = 1
                        changed = True
            if changed:
                copied.add(j)
                break

    for bi, rows in enumerate(bands):
        if bi in copied:
            continue
        positions = {r: [c for c in range(w) if grid[r][c] == foreground] for r in rows}
        right = {r: max(positions[r]) for r in rows}
        run = {}
        terminal = {}
        for r in rows:
            best = cur = 0
            prev = -2
            for c in positions[r]:
                cur = cur + 1 if c == prev + 1 else 1
                best = max(best, cur)
                prev = c
            run[r] = best
            terminal[r] = cur
        max_run = max(run.values())
        max_right = max(right.values())

        # Repeated two-color suffixes show which later cells belong to the pattern.
        periodic = {}
        for r in rows:
            m = right[r]
            bits = [grid[r][c] == foreground for c in range(w)]
            found = []
            for period in range(2, min(8, w // 2) + 1):
                for s in range(m + 1):
                    for e in range(m, min(w - 1, m + period) + 1):
                        if e - s + 1 < 2 * period - 1:
                            continue
                        motif = bits[s:s+period]
                        if not any(motif) or all(motif):
                            continue
                        if all(bits[k] == motif[(k-s) % period] for k in range(s, e+1)):
                            found.append((period, s, e, motif))
            if found:
                periodic[r] = min(found, key=lambda x: (x[0], -x[2], x[1]))

        # A sparse row can establish a stride for the longest row in the same band.
        sparse_rows = []
        for r in rows:
            ps = positions[r]
            if len(ps) >= 2 and all(c % 2 == ps[0] % 2 for c in ps) and ps[-1] - ps[0] >= 4:
                sparse_rows.append(r)
        sparse_targets = set()
        for r in sparse_rows:
            phase = right[r] % 2
            for t in rows:
                if t != r and run[t] != max_run:
                    continue
                if right[t] % 2 != phase:
                    continue
                sparse_targets.add(t)
                for c in range(right[t] + 1, w, 2):
                    if c % 2 == phase and grid[t][c] == background:
                        out[t][c] = 1

        for r, (period, s, e, motif) in periodic.items():
            if period == 2:
                for c in range(e + 1, w):
                    if motif[(c-s) % period] and grid[r][c] == background:
                        out[r][c] = 1

        # Extend a dominant solid terminal bar through the remaining cells.
        solid = {r for r in rows if r not in periodic and r not in sparse_targets}
        chosen = {r for r in solid if run[r] == max_run}
        chosen.update(r for r in solid if terminal[r] >= 5 and right[r] == max_right)
        if len(rows) == 1:
            chosen.add(rows[0])
        for r in chosen:
            for c in range(right[r] + 1, w):
                if grid[r][c] == background:
                    out[r][c] = 1
    return out

def transform(grid):
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [any(x != background for x in row) for row in grid]
    blocks = []
    start = None
    for r, is_active in enumerate(active + [False]):
        if is_active and start is None:
            start = r
        elif not is_active and start is not None:
            blocks.append(list(range(start, r)))
            start = None
    if len(blocks) < 2:
        return out
    counts = [sum(grid[r][c] != background for r in block for c in range(len(grid[0]))) for block in blocks]
    target_i = min(range(len(blocks)), key=lambda i: counts[i])
    donor_i = max(range(len(blocks)), key=lambda i: counts[i])
    target, donor = blocks[target_i], blocks[donor_i]
    if len(target) != len(donor):
        return out
    for tr, dr in zip(target, donor):
        colored = [c for c, x in enumerate(grid[tr]) if x != background]
        if not colored:
            continue
        last = max(colored)
        for c in range(last + 1, len(grid[tr])):
            if grid[tr][c] == background and grid[dr][c] != background:
                out[tr][c] = 1
    return out

